import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.BiXHgXAn.js";const k=JSON.parse('{"title":"Up-to-date checks","description":"Skip unchanged builds, check whether work is already done, and choose between source fingerprints and status commands.","frontmatter":{"title":"Up-to-date checks","description":"Skip unchanged builds, check whether work is already done, and choose between source fingerprints and status commands.","section":"Guide","docType":"guide","outline":"deep"},"headers":[],"relativePath":"docs/guide/up-to-date.md","filePath":"next/docs/guide/up-to-date.md"}'),n={name:"docs/guide/up-to-date.md"};function h(l,s,p,d,o,c){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="skipping-work-that-is-up-to-date" tabindex="-1">Up-to-date checks <a class="header-anchor" href="#skipping-work-that-is-up-to-date" aria-label="Permalink to &quot;Up-to-date checks {#skipping-work-that-is-up-to-date}&quot;">​</a></h1><p>A build should run when its inputs change or its output is missing. Declare those files with <code>sources</code> and <code>generates</code>, and Task can skip the commands on your next run. For other kinds of work, use <code>status</code> to check whether the result is already available.</p><h2 id="by-fingerprinting-locally-generated-files-and-their-sources" tabindex="-1">Skip unchanged builds <a class="header-anchor" href="#by-fingerprinting-locally-generated-files-and-their-sources" aria-label="Permalink to &quot;Skip unchanged builds {#by-fingerprinting-locally-generated-files-and-their-sources}&quot;">​</a></h2><p>For a Go application in <code>main.go</code>, declare the source file and the executable that the build produces:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">main.go</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    generates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;app{{exeExt}}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go build -o app{{exeExt}} main.go</span></span></code></pre></div><p>Run <code>task build</code> to create the executable. Run it again without changing <code>main.go</code>, and Task reports that <code>build</code> is up to date. Edit <code>main.go</code> or delete the executable, and the next call builds it again.</p><p>The default method, <code>checksum</code>, compares the content of source files with a saved fingerprint. It checks that declared outputs exist; it does not compare their contents. Editing the executable alone will not trigger a rebuild.</p><p>These checks skip the task&#39;s commands. Its <a href="./dependencies">dependencies</a> still run first and perform their own up-to-date checks.</p><h3 id="track-the-right-files" tabindex="-1">Track the right files <a class="header-anchor" href="#track-the-right-files" aria-label="Permalink to &quot;Track the right files&quot;">​</a></h3><p><code>sources</code> and <code>generates</code> accept files and glob patterns, relative to the task&#39;s <a href="./defining-tasks#task-directory">working directory</a>. Include every file that affects the result, such as source code, configuration, and dependency lockfiles.</p><p>For a Go module with several source files, replace <code>sources</code> and <code>cmds</code> in the example above with:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;**/*.go&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go.mod</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go.sum</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">exclude</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;**/*_test.go&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go build -o app{{exeExt}} .</span></span></code></pre></div><p>Patterns are evaluated in order. Put each <code>exclude</code> after the positive glob it narrows. Here, test files are excluded because this task builds the application; a test task should track them.</p><p>Set <code>use_gitignore: true</code> at the root of the Taskfile to filter glob matches using <code>.gitignore</code> rules. A task can override that setting. Keep it disabled for tasks that need to track ignored files as inputs.</p><p><code>generates</code> is optional. A task such as a test suite can use <code>sources</code> alone to skip work when its inputs have not changed. <code>generates</code> alone does not provide a file fingerprint; use <code>status</code> if you only need to check that a result exists.</p><h3 id="choose-a-check-method" tabindex="-1">Choose a check method <a class="header-anchor" href="#choose-a-check-method" aria-label="Permalink to &quot;Choose a check method&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>How it checks sources</th></tr></thead><tbody><tr><td><code>checksum</code> (default)</td><td>Compares file contents with a saved fingerprint.</td></tr><tr><td><code>timestamp</code></td><td>Compares modification times with outputs and Task&#39;s saved timestamp.</td></tr><tr><td><code>none</code></td><td>Disables file-based skipping.</td></tr></tbody></table><p>To use modification times for the build above, add <code>method: timestamp</code> to the task:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    method</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">timestamp</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">main.go</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    generates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;app{{exeExt}}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go build -o app{{exeExt}} main.go</span></span></code></pre></div><p>You can also set <code>method</code> at the root of the Taskfile to change the default for all tasks. A task&#39;s own setting takes precedence.</p><p>With <code>timestamp</code>, touching a source can cause a rerun even if its content has not changed. Without <code>generates</code>, Task uses its saved timestamp for the comparison. Use <code>method: none</code> when <code>sources</code> should drive <a href="./watch">watch mode</a> without making the task up to date.</p><h2 id="using-programmatic-checks-to-indicate-a-task-is-up-to-date" tabindex="-1">Check existing work <a class="header-anchor" href="#using-programmatic-checks-to-indicate-a-task-is-up-to-date" aria-label="Permalink to &quot;Check existing work {#using-programmatic-checks-to-indicate-a-task-is-up-to-date}&quot;">​</a></h2><p>Use <code>status</code> when a command can determine whether work is needed. Every check must exit with code <code>0</code> for Task to skip the commands. If any check fails, Task runs the commands:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  prepare</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test -d directory</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test -f directory/file1.txt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test -f directory/file2.txt</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mkdir -p directory</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">touch directory/file1.txt directory/file2.txt</span></span></code></pre></div><p>Run <code>task prepare</code> twice: the first call creates the files, and the second skips the commands. Delete either file, and Task runs the commands again.</p><p>Keep status checks fast and read-only: they may run each time the task is called. They can inspect files, installed tools, services, or remote artifacts. A failed check means &quot;do the work&quot;, so the commands should handle partially completed work, as <code>mkdir -p</code> does above.</p><p>If a failed check should stop execution with an error, use <a href="./conditional-execution#using-programmatic-checks-to-cancel-the-execution-of-a-task-and-its-dependencies">preconditions</a>.</p><h3 id="combine-files-and-status" tabindex="-1">Combine files and status <a class="header-anchor" href="#combine-files-and-status" aria-label="Permalink to &quot;Combine files and status&quot;">​</a></h3><p>Use both <code>sources</code> and <code>status</code> when the result depends on local files but cannot be checked with <code>generates</code>. This Docker example tags the image with a checksum of its build inputs:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Dockerfile</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">src/**/*</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">docker image inspect example/app:{{.CHECKSUM}} &gt; /dev/null 2&gt;&amp;1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">docker build -t example/app:{{.CHECKSUM}} .</span></span></code></pre></div><p>Task skips the build only when the sources are unchanged <strong>and</strong> the status check succeeds. A changed source produces a new tag; a missing image makes the check fail. Include any other files used by your Dockerfile in <code>sources</code>.</p><p>You can also combine <code>sources</code>, <code>generates</code>, and <code>status</code>: every configured check must pass for Task to consider the work up to date.</p><h3 id="use-source-values" tabindex="-1">Use source values <a class="header-anchor" href="#use-source-values" aria-label="Permalink to &quot;Use source values&quot;">​</a></h3><p>With <code>method: checksum</code>, <span><code>{{.CHECKSUM}}</code></span> contains the source fingerprint. With <code>method: timestamp</code>, <span><code>{{.TIMESTAMP}}</code></span> contains the latest source modification time. Both can be used in <code>cmds</code> and <code>status</code>; they describe the sources, not the generated files.</p><p><code>.TIMESTAMP</code> is a Go <code>time.Time</code> value. For example, <span><code>{{.TIMESTAMP.Unix}}</code></span> produces a Unix timestamp, and <span><code>{{.TIMESTAMP.Format &quot;2006-01-02&quot;}}</code></span> formats a date.</p><h2 id="check-or-force-a-run" tabindex="-1">Check or force a run <a class="header-anchor" href="#check-or-force-a-run" aria-label="Permalink to &quot;Check or force a run&quot;">​</a></h2><p>To check whether tasks are up to date without running their commands:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>You can pass multiple task names. The command exits with a non-zero <a href="./../reference/cli#exit-codes">exit code</a> if any task is not up to date.</p><p>To run a task even when its checks say the work is already done:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><code>-f</code> is the short form of <code>--force</code>. To rerun automatically when files change, use <a href="./watch">Watch mode</a>.</p><h2 id="track-different-inputs" tabindex="-1">Track different inputs <a class="header-anchor" href="#track-different-inputs" aria-label="Permalink to &quot;Track different inputs&quot;">​</a></h2><p>With the checksum method, Task stores one source fingerprint per task label. If build variables affect the result, include them in the label and use separate output paths. For example, to build with different Go build tags:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;build-{{.MODE}}&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">main.go</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    generates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;app-{{.MODE}}{{exeExt}}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go build -tags &#39;{{.MODE}}&#39; -o app-{{.MODE}}{{exeExt}} main.go</span></span></code></pre></div><p>Run <code>task build MODE=debug</code>, then <code>task build MODE=release</code>. Each mode has its own executable and saved checksum, so a later <code>task build MODE=debug</code> can skip the build. A change to <code>main.go</code> makes both modes need a rebuild when next called.</p><p>These saved checks apply across invocations. To limit repeated task calls within a single invocation, use <a href="./dependencies#repeated-calls"><code>run: once</code> or <code>run: when_changed</code></a>.</p><h2 id="store-fingerprints" tabindex="-1">Store fingerprints <a class="header-anchor" href="#store-fingerprints" aria-label="Permalink to &quot;Store fingerprints&quot;">​</a></h2><p>Task stores its file fingerprints in <code>.task/</code> under the project directory. Usually, add this directory to <code>.gitignore</code>. For generated code committed to version control, you may choose to commit the corresponding checksum too.</p><p>Set <code>TASK_TEMP_DIR</code> to store fingerprints elsewhere:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TASK_TEMP_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;~/.task&#39;</span></span></code></pre></div><p>Relative paths, such as <code>tmp/task</code>, are resolved from the project directory. Absolute paths and paths starting with <code>~</code> use a separate subdirectory for each project.</p>`,52)])])}const u=e(n,[["render",h]]);export{k as __pageData,u as default};
